#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
BIN="$REPO_ROOT/bin/memory.js"
TEST_DIR="${AI_MEMORY_TEST_DIR:-/tmp/opencode/mcp-test-project}"

# snap prints a canonical digest snapshot of every ai-memory repo surface the
# test must leave untouched: the store (db + WAL sidecars) and any OpenCode
# config files. One line per surface: "<sha256|absent> <name>".
snap() {
  local p f
  for p in "$REPO_ROOT/.ai-memory/memory.db" "$REPO_ROOT/.ai-memory/memory.db-wal" "$REPO_ROOT/.ai-memory/memory.db-shm"; do
    if [[ -f "$p" ]]; then printf '%s %s\n' "$(sha256sum "$p" | cut -d' ' -f1)" "${p##*/}"
    else printf 'absent %s\n' "${p##*/}"; fi
  done
  for f in opencode.json opencode.jsonc .opencode/opencode.json .opencode/opencode.jsonc; do
    p="$REPO_ROOT/$f"
    if [[ -e "$p" ]]; then printf '%s %s\n' "$(sha256sum "$p" | cut -d' ' -f1)" "$f"
    else printf 'absent %s\n' "$f"; fi
  done
}

banner "Test de la surface MCP — isolation garantie"

# ── Stage 1: preflight + throwaway project ────────────────────────────────
stage "Preflight + projet jetable"

say "Le test se joue dans un projet jetable, jamais dans ce repo."
note "  projet de test : $TEST_DIR"
note "  serveur testé  : $BIN mcp"
say ""
if [[ -d "$TEST_DIR" ]] && [[ -n "$(ls -A "$TEST_DIR" 2>/dev/null)" ]]; then
  if ! confirm "Le projet de test existe déjà — le réinitialiser (rm -rf + recréer) ?"; then
    warn "gardé tel quel ; les étapes suivantes repartiront de cet état"
  else
    rm -rf "$TEST_DIR"
    say "ancien projet de test supprimé"
  fi
fi
mkdir -p "$TEST_DIR"

# A stale MCP server from a previous run survives the reset and keeps writing
# into a deleted inode while the service still reports it "connected" — the
# observed failure mode. Kill it BEFORE touching the directory.
if pgrep -f "$BIN mcp" >/dev/null 2>&1; then
  pkill -f "$BIN mcp" || true
  sleep 1
  say "serveur MCP de test résiduel terminé (il survivait à la réinitialisation)"
fi

step "Vérification des prérequis…"
command -v node >/dev/null 2>&1     || { warn "node absent — impossible de continuer"; exit 1; }
command -v opencode >/dev/null 2>&1 || { warn "opencode absent — impossible de continuer"; exit 1; }
[[ -f "$BIN" ]]                     || { warn "bin/memory.js introuvable à $BIN"; exit 1; }
say "✓ node, opencode v$(opencode --version 2>/dev/null | grep -oE '[0-9]+\.[0-9]+\.[0-9]+' | head -1), binaire présent"

DIGEST_BEFORE="$(snap)"

note "  Surfaces photographiées (digest sha256, comparées à la fin) :"
while IFS= read -r line; do note "    - ${line#* }"; done <<< "$DIGEST_BEFORE"

say ""
warn "Contrat d'isolation :"
note "  - le serveur monté ouvre le store du PROJET JETABLE (chemin relatif au cwd)"
note "  - tout ce que le test crée vit dans $TEST_DIR (config + store)"
note "  - la réversibilité totale = supprimer ce dossier (étape finale)"
warn "  - garde les sessions du repo ai-memory au repos pendant le test"
pause "Projet prêt — Enter pour monter le serveur"

cd "$TEST_DIR"

# ── Stage 2: mount + connection check ─────────────────────────────────────
stage "Montage du serveur MCP (dans le projet jetable)"

step "Enregistrement du serveur (la config est écrite DANS le projet jetable)…"
# Absolute node path: the service may run with a different PATH than the
# interactive shell (nvm-managed node would not resolve there).
NODE_BIN="$(command -v node)"
if ! opencode mcp add memory -- "$NODE_BIN" "$BIN" mcp; then
  warn "opencode mcp add a échoué — vérifie la version de l'CLI et la syntaxe"
  SKIPPED+=("opencode mcp add en échec")
fi
note "  config : $TEST_DIR/opencode.json"
say ""
step "État de la connexion (avec retries — le service peut découvrir la config avec un peu de retard)…"
MCP_LINE=""
for _i in 1 2 3 4 5 6 7 8; do
  MCP_LINE="$(opencode mcp list 2>/dev/null | tr -d '\r' | grep -w memory | head -1 || true)"
  if printf '%s' "$MCP_LINE" | grep -wq connected; then break; fi
  sleep 2
done
if printf '%s' "$MCP_LINE" | grep -wq connected; then
  say "✓ $MCP_LINE"
elif [[ -n "$MCP_LINE" ]]; then
  note "  le serveur est monté (il figure dans la liste) mais pas encore 'connected' :"
  note "  $MCP_LINE"
  note "  pas bloquant — la preuve définitive est l'étape 3 : les outils memory_* dans la session"
else
  warn "le serveur n'apparaît pas dans la liste — vérifie via /mcps dans la TUI à l'étape 3"
fi
pause "Enter quand tu es prêt pour la session de test"

# ── Stage 3: the session — the ritual, live ───────────────────────────────
stage "La session — le rituel par un agent réel"

say "Tu auras besoin de deux terminaux : celui-ci (le wizard attend) et un autre"
say "pour la session OpenCode. Dans l'autre terminal :"
step "cd $TEST_DIR"
step "lance : opencode"
step "colle les prompts ci-dessous, un par un — le wizard attend ta réponse"
say "entre chaque prompt ; le prompt reste affiché ici pendant que tu testes"
say ""

PROMPTS=(
  "1 · RITUEL — Utilise l'outil memory_recover du serveur MCP « memory » et rapporte : nombre de directives, nombre de summaries, et les stats. · Attendu : 0 directives, 0 summaries, stats à zéro (store vierge)."
  "2 · ÉCRITURE — Utilise l'outil memory_store pour enregistrer exactement : « Mémoire de test MCP (projet jetable) », metadata {\"kind\":\"note\",\"tags\":[\"mcp-test\"]}, weight 0.6. Donne-moi l'id retourné. · Attendu : un id UUID."
  "3 · RECHERCHE — Utilise l'outil memory_search avec la requête « MCP » : la mémoire de test apparaît-elle, avec quel rang ? · Attendu : trouvée, rang 1."
  "4 · IMMUTABILITÉ — Utilise memory_supersede sur cette mémoire avec le contenu « Mémoire de test MCP révisée », puis memory_get sur l'ancien id : quel est son status ? · Attendu : un nouvel id, et l'ancien est « superseded »."
  "5 · ÉTAT — Utilise memory_stats : combien de mémoires actives ? · Attendu : 1 (la révisée)."
)
for p in "${PROMPTS[@]}"; do
  say ""
  say "  ┌── prompt à coller ─────────────────────────────────────────────"
  say "  │ $p" | fold -s -w 100 | sed 's/^/  /'
  say "  └────────────────────────────────────────────────────────────────"
  confirm "comportement observé conforme ?" && say "  ✓ conforme" || SKIPPED+=("prompt $p non conforme (note ce que l'agent a répondu)")
done

say ""
pause "Referme la session de test (Ctrl-C puis Enter ici pour continuer)"

# ── Stage 4: external verification ────────────────────────────────────────
stage "Vérification externe (le wizard prouve, pas l'agent)"

if [[ -f "$TEST_DIR/.ai-memory/memory.db" ]]; then
  say "✓ un store a bien été créé DANS le projet jetable : $TEST_DIR/.ai-memory/memory.db"
else
  warn "aucun store trouvé dans le projet jetable — où l'agent a-t-il écrit ?"
  SKIPPED+=("store du projet jetable introuvable")
fi

say ""
step "Relecture du store de test par le CLI (hors MCP) :"
if node "$BIN" --db "$TEST_DIR/.ai-memory/memory.db" list 2>/dev/null | grep -q "Mémoire de test MCP"; then
  say "✓ la mémoire de test est dans le store DU PROJET JETABLE (les écritures de l'agent n'ont pas fuité)"
else
  warn "la mémoire de test ne se relit pas dans le store du projet jetable"
  SKIPPED+=("écritures de l'agent non relues dans le store de test")
fi

DIGEST_AFTER="$(snap)"
if [[ "$DIGEST_BEFORE" == "$DIGEST_AFTER" ]]; then
  say "✓ digests identiques : la mémoire du repo ai-memory et ses configs n'ont JAMAIS été touchées"
else
  warn "DIGESTS DIFFÉRENTS — une surface du repo a bougé pendant le test :"
  diff <(printf '%s\n' "$DIGEST_BEFORE") <(printf '%s\n' "$DIGEST_AFTER") | sed 's/^/    /' || true
  SKIPPED+=("digest du repo modifié pendant le test — investiguer avant tout nouveau test")
fi

pause "Enter pour la réversibilité"

# ── Stage 5: reversal — delete the throwaway project ──────────────────────
stage "Réversibilité — suppression du projet jetable"

say "Tout ce que le test a créé vit dans :"
note "  $TEST_DIR"
say "Le supprimer rend l'état antérieur au test, au bit près."

if confirm "Supprimer le projet de test maintenant ?"; then
  pkill -f "$BIN mcp" 2>/dev/null || true
  sleep 1
  rm -rf "$TEST_DIR"
  say "✓ projet de test supprimé — le montage MCP vivait dans sa config : retiré avec lui"
  say "  (aucune trace hors du dossier : pas d'écriture globale, pas d'OAuth, pas d'état service)"
  DIGEST_FINAL="$(snap)"
  if [[ "$DIGEST_BEFORE" == "$DIGEST_FINAL" ]]; then
    say "✓ digests toujours identiques : le repo ai-memory est exactement dans son état d'avant le test"
  else
    warn "digest final différent — investiguer"
    SKIPPED+=("digest final modifié après cleanup")
  fi
else
  note "projet conservé : le serveur 'memory' reste monté DANS ce projet tant que la config existe"
  note "  pour le retirer plus tard : rm -rf $TEST_DIR, ou retire l'entrée mcp.servers.memory"
  note "  de $TEST_DIR/opencode.json — rien d'autre n'existe nulle part ailleurs"
fi

finish

if (( ${#SKIPPED[@]} == 0 )); then
  note "Verdict : surface MCP conforme, isolée, réversible. Le montage est réversible par construction."
else
  warn "Verdict : ${#SKIPPED[@]} point(s) à revoir — voir la liste ci-dessus."
fi
